// Signed Integer Overflow
int x = 2147483647; // INT_MAX
int y = x + 1;      // Undefined Behavior (UB)

// Shift Operations
int a = 1;
int b = a << 32;    // UB: Shift >= bits in type

int c = -1;
int d = c >> 1;     // UB: Right shift negative signed value (mostly)

// Division by Zero
int num = 10;
int zero = 0;
int result = num / zero; // UB

// Invalid Pointer Dereference
int* p = nullptr;
*p = 42;            // UB

// Accessing out of bounds array
int arr[5];
arr[5] = 10;        // UB
